use xiom.io;
type Fighter = {
  name: Str;
  hp: Int;
  power: Int;
}

fn take_damage(fighter: &mut Fighter, amount: Int) {
  fighter.hp -= amount;
  if fighter.hp < 0 { fighter.hp = 0; };
}

fn is_alive(fighter: &Fighter) -> Bool {
  fighter.hp > 0
}

fn main() -> Int {
  var hero = Fighter{ name: "Hero", hp: 100, power: 20 };
  var enemy = Fighter{ name: "Goblin", hp: 40, power: 8 };

  take_damage(&mut enemy, hero.power);
  io.println(enemy.hp.to_str());
  take_damage(&mut enemy, hero.power);
  io.println(enemy.hp.to_str());
  io.println(is_alive(&enemy).to_str());
  return 0;
}
